import type { LatLngTuple } from '@/lib/map/polyline';
import segmentsJson from './segments.json';

// Generated by scripts/build-train-segments.mjs from the OSM track geometry in src/lib/map/krl-lines.json.

export type SegmentKey = string; // `${lineId}:${fromCode}-${toCode}`
export type SegmentLineId = 'bogor' | 'cikarang';

// JSON arrays type as number[]; the script writes [lat, lon] pairs, which the tests check.
const data = segmentsJson as unknown as { stations: Record<string, LatLngTuple>; segments: Record<SegmentKey, LatLngTuple[]> };

export const STATION_COORDS: Record<string, LatLngTuple> = data.stations;
export const SEGMENTS: Record<SegmentKey, LatLngTuple[]> = data.segments;

/** Track from one station to the next, in travel order; null when the segment is not built. */
export function segmentPath(lineId: SegmentLineId, fromCode: string, toCode: string): LatLngTuple[] | null {
  const forward = SEGMENTS[`${lineId}:${fromCode}-${toCode}`];
  if (forward) return forward;
  const backward = SEGMENTS[`${lineId}:${toCode}-${fromCode}`];
  return backward ? [...backward].reverse() : null;
}
